create table offers (id uuid primary key,name varchar(255) not null,customer varchar(255),language varchar(32) not null,presentation_language varchar(32) not null,input_drive_folder text,output_drive_folder text,presentation_name varchar(255) not null,ai_provider varchar(64) not null,models_json text not null,presentation_guidance_json text,current_phase varchar(32) not null,status varchar(32) not null,created_at timestamptz not null,updated_at timestamptz not null);
create table phase_executions (id uuid primary key,offer_id uuid not null references offers(id) on delete cascade,phase varchar(32) not null,status varchar(32) not null,version integer not null,error_message text,started_at timestamptz,completed_at timestamptz,unique(offer_id,phase));
create table artifacts (id uuid primary key,offer_id uuid not null references offers(id) on delete cascade,phase varchar(32) not null,type varchar(64) not null,version integer not null,content text not null,created_at timestamptz not null);
create index idx_artifacts_offer_type on artifacts(offer_id,type,version desc);
create table agent_executions (id uuid primary key,offer_id uuid not null references offers(id) on delete cascade,phase varchar(32) not null,agent_key varchar(128) not null,status varchar(32) not null,objective text,output text,model varchar(128),input_tokens bigint not null default 0,output_tokens bigint not null default 0,provider_request_id varchar(255),started_at timestamptz,completed_at timestamptz,error_message text);
create index idx_agent_exec_offer on agent_executions(offer_id,started_at);
